-- CASE-PUMP-010: M06 component reference (m06_equipment_component_reference): both 'Impeller' (PUMP.HYDR.IMPL), 'Impeller and Casing Volute' (PUMP.HYDR.RECR) and 'Impeller and Wear Rings' (PUMP.HYDR.WEAR) belong to subsystem 'Hydraulic End' for EQ-PUMP; no other EQ-PUMP subsystem lists an impeller or casing component. Subsystem only: component_name and taxonomy_code stay NULL because the case could map to PUMP.HYDR.IMPL or PUMP.HYDR.RECR (ambiguous).
UPDATE operational_case SET subsystem_id = (SELECT subsystem_id FROM subsystem WHERE subsystem_name = 'Hydraulic End')
WHERE case_reference = 'CASE-PUMP-010' AND equipment_class_id = 'EQ-PUMP' AND subsystem_source_label = 'Impeller and casing' AND subsystem_id IS NULL;
UPDATE historical_case h SET subsystem_id = c.subsystem_id FROM operational_case c WHERE h.case_id = c.case_id AND c.case_reference = 'CASE-PUMP-010';

